src/combine.js (7 lines)
1→/**
2→ * Combine one line's counts into a single number. A count that is not a
3→ * number counts as zero (docs/design.md, "Lenient counts").
4→ */
5→export function combine(counts) {
6→  return counts.reduce((sum, n) => sum + (Number.isNaN(n) ? 0 : n), 0);
7→}

